/**
 * img.ts: image helpers shared by every photo component.
 *  - imgSrc / srcset : responsive WebP (480w / 960w) with a JPG fallback. In the single-file build the WebPs are inlined.
 *  - photoEl()       : <picture> with blur-up placeholder, skeleton shimmer, lazy loading, focal point (object-position)
 *                      and an initials fallback when the file is missing.
 *  - Avatar()        : circular avatar (best photo) with optional glow ring + "breathing" animation.
 * Files live in /public/images/me-N.jpg (+ me-N-480.webp, me-N-960.webp generated by `npm run images`).
 */
import { data, Photo } from './data';
import { h } from './util';
import { INLINE, META } from './imgs.gen';

export const BASE = 'images/';
export const best = (): Photo | undefined => data.photos.find(p => p.best) || data.photos[0];
const stem = (p: Photo) => p.file.replace(/\.\w+$/, '');
export const meta = (p: Photo) => META[stem(p)] || { blur: '', w: 4, h: 3 };
export const ratio = (p: Photo) => { const m = meta(p); return m.w / m.h; };
const webp = (p: Photo, w: number) => INLINE[`${stem(p)}-${w}.webp`] || `${BASE}${stem(p)}-${w}.webp`;
export const srcset = (p: Photo) => `${webp(p, 480)} 480w, ${webp(p, 960)} 960w`;
export const imgSrc = (p: Photo, big = false) => big && !INLINE[`${stem(p)}-960.webp`] ? BASE + p.file : webp(p, big ? 960 : 480);
export const fp = (p: Photo) => `${p.focal?.x ?? 50}% ${p.focal?.y ?? 40}%`;
export const initials = () => data.name.split(/\s+/).map(w => w[0]).slice(0, 2).join('').toUpperCase();

/** Photo with skeleton + blur-up. `cls` extra classes, `sizes` the HTML sizes attr, `eager` to skip lazy loading. */
export function photoEl(p: Photo, o: { cls?: string; sizes?: string; eager?: boolean; contain?: boolean } = {}): HTMLElement {
  const m = meta(p);
  const wrap = h('div', { class: 'pic skel ' + (o.cls || ''), style: m.blur ? { backgroundImage: `url(${m.blur})` } : {} });
  const img = h('img', { alt: p.alt, decoding: 'async', loading: o.eager ? 'eager' : 'lazy', sizes: o.sizes || '(max-width:700px) 90vw, 480px', srcset: srcset(p), src: imgSrc(p), draggable: 'false' }) as HTMLImageElement;
  img.style.objectPosition = fp(p); if (o.contain) img.style.objectFit = 'contain';
  const ok = () => { wrap.classList.remove('skel'); wrap.classList.add('ready'); };
  img.addEventListener('load', ok);
  img.addEventListener('error', () => { wrap.classList.remove('skel'); wrap.classList.add('missing'); img.remove(); wrap.append(h('span', { class: 'ini', role: 'img', 'aria-label': p.alt }, initials())); });
  wrap.append(img); if (img.complete && img.naturalWidth) ok(); return wrap;
}

/** Circular avatar. size in px. glow = soft ring, breathe = slow scale pulse (disabled by reduced motion). Falls back to initials. */
export function Avatar(size = 40, o: { glow?: boolean; breathe?: boolean; cls?: string } = {}): HTMLElement {
  const p = best(); const box = h('span', { class: `avatar${o.glow ? ' glow' : ''}${o.breathe ? ' breathe' : ''} ${o.cls || ''}`, style: { width: size + 'px', height: size + 'px', fontSize: size * 0.38 + 'px' } });
  if (!p) { box.append(h('span', { class: 'ini' }, initials())); return box; }
  const pe = photoEl(p, { cls: 'av-pic', eager: true, sizes: size > 100 ? '240px' : '96px' }); box.append(pe); return box;
}
